INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O crânio humano é composto por ossos neurocranianos e viscerocranianos. Qual destes ossos é ÍMPAR e contém a ''sela túrcica'', que abriga a glândula hipófise?","options":{"a":"Osso Frontal.","b":"Osso Etmoide.","c":"Osso Esfenoide.","d":"Osso Occipital.","e":"Osso Parietal."},"answer":"c","rationale":"O esfenoide é o osso ''chave'' da base do crânio e contém a fossa hipofisária (sela túrcica).","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Osteologia do neurocrânio.","d":"Errada.","e":"Errada. É um osso par."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Osteologia"]}', '36e2bfb00d40738c6e67188ef31a0bbf', 450, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''lâmina cribriforme'' (crivosa) permite a passagem das fibras do nervo olfatório. A qual osso ela pertence?","options":{"a":"Esfenoide.","b":"Etmoide.","c":"Vômer.","d":"Palatino.","e":"Maxila."},"answer":"b","rationale":"O etmoide situa-se no assoalho da fossa anterior do crânio e teto da cavidade nasal.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia da base do crânio.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Osteologia"]}', '1e51b98f52664280f7f1cc7fa9ef8b7d', 451, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual o principal músculo da mastigação responsável pelo FECHAMENTO potente da mandíbula e que se origina na fossa temporal?","options":{"a":"Masseter.","b":"Temporal.","c":"Pterigoideo medial.","d":"Pterigoideo lateral.","e":"Bucinador."},"answer":"b","rationale":"O músculo temporal eleva a mandíbula e suas fibras posteriores realizam retração.","option_rationales":{"a":"Errada. Também fecha, mas origina-se no arco zigomático.","b":"Correta. Miologia da mastigação.","c":"Errada.","d":"Errada. Responsável por protrusão e abertura.","e":"Errada. Músculo da expressão facial."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Miologia"]}', 'eb5c248312134f373c7b962fe246cd92', 452, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A paralisia de Bell resulta de uma lesão em qual nervo craniano, afetando a musculatura da expressão facial?","options":{"a":"Nervo Trigêmeo (V).","b":"Nervo Facial (VII).","c":"Nervo Glossofaríngeo (IX).","d":"Nervo Vago (X).","e":"Nervo Hipoglosso (XII)."},"answer":"b","rationale":"O nervo facial inerva todos os músculos da expressão facial (derivados do 2º arco branquial).","option_rationales":{"a":"Errada. É o nervo da sensibilidade da face e mastigação.","b":"Correta. Neurologia dos nervos cranianos.","c":"Errada.","d":"Errada.","e":"Errada. Inerva a língua."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', '75208ee5ea41917ae1ce17dfa709c7ce', 453, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''nervo trigêmeo'' possui três divisões principais. Qual delas é a única que possui fibras MOTORAS?","options":{"a":"Nervo Oftálmico (V1).","b":"Nervo Maxilar (V2).","c":"Nervo Mandibular (V3).","d":"Todas as divisões são puramente motoras.","e":"Nenhuma divisão possui fibras motoras."},"answer":"c","rationale":"O V3 (mandibular) carrega a raiz motora para os músculos da mastigação, além da sensibilidade da parte inferior da face.","option_rationales":{"a":"Errada. Puramente sensitivo.","b":"Errada. Puramente sensitivo.","c":"Correta. Organização funcional do trigêmeo.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', '7890d2d15f49f77b546e3a77e91b2aec', 454, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''glândula parótida'' é a maior das glândulas salivares. Qual nervo craniano atravessa o seu parênquima (podendo ser lesado em cirurgias de parótida), embora NÃO a inerve?","options":{"a":"Nervo Trigêmeo.","b":"Nervo Facial.","c":"Nervo Glossofaríngeo.","d":"Nervo Vago.","e":"Nervo Acessório."},"answer":"b","rationale":"O plexo parotídeo do nervo facial situa-se dentro da glândula. A inervação secretora da parótida é dada pelo nervo glossofaríngeo (via nervo petroso menor).","option_rationales":{"a":"Errada.","b":"Correta. Anatomia aplicada da região parotídea.","c":"Errada. Este realiza a inervação funcional, mas não atravessa o plexo da mesma forma.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia/Clínica"]}', 'e022562501b37d4eab27d313207f6498', 455, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''polígono de Willis'' (círculo arterial do cérebro) fornece circulação colateral. Qual artéria conecta o sistema carotídeo interno ao sistema vertebrobasilar posteriormente?","options":{"a":"Artéria Comunicante Anterior.","b":"Artéria Comunicante Posterior.","c":"Artéria Cerebral Média.","d":"Artéria Basilar.","e":"Artéria Vertebral."},"answer":"b","rationale":"As comunicantes posteriores ligam a carótida interna às artérias cerebrais posteriores (ramos da basilar).","option_rationales":{"a":"Errada. Liga as duas cerebrais anteriores.","b":"Correta. Vascularização do sistema nervoso central.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Angiologia/Neuroanatomia"]}', '9a6b1664e7d563bff9c045f03e32def4', 456, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''veia jugular interna'' sai do crânio através de qual forame?","options":{"a":"Forame Magno.","b":"Forame Jugular.","c":"Forame Oval.","d":"Canal Carótico.","e":"Forame Redondo."},"answer":"b","rationale":"O forame jugular abriga a veia jugular interna e os nervos cranianos IX, X e XI.","option_rationales":{"a":"Errada. Passagem da medula/artérias vertebrais.","b":"Correta. Base do crânio.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Angiologia/Osteologia"]}', '7a7bf4338390bff4e7e3a3c79e88b146', 457, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual o único músculo da língua que NÃO é inervado pelo nervo Hipoglosso (XII), sendo inervado pelo plexo faríngeo (Vago)?","options":{"a":"Genioglosso.","b":"Hioglosso.","c":"Estiloglosso.","d":"Palatoglosso.","e":"Longitudinal superior."},"answer":"d","rationale":"O palatoglosso é tecnicamente um músculo do palato mole e da língua, inervado pelo X.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Errada.","d":"Correta. Inervação motora da língua.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Miologia/Neuroanatomia"]}', '8c21e25587aad36526ec0974144a51bd', 458, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A glândula tireoide situa-se no pescoço anterior. Qual estrutura anatômica a tireoide ''abraça'' ou circunda?","options":{"a":"Esôfago apenas.","b":"Traqueia (anéis traqueais superiores).","c":"Glândula submandibular.","d":"Nervo vago.","e":"Artéria carótida interna."},"answer":"b","rationale":"O istmo da tireoide cruza geralmente o 2º e 3º anéis traqueais.","option_rationales":{"a":"Errada.","b":"Correta. Esplanccnologia do pescoço.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', '63b1d609428f75df283fa524b0b40527', 459, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''nervo laríngeo recorrente'' (ramo do vago) tem um trajeto diferente nos dois lados do corpo. Qual estrutura ele contorna no lado ESQUERDO antes de subir para a laringe?","options":{"a":"Artéria subclávia.","b":"Arco da aorta.","c":"Veia cava superior.","d":"Artéria carótida comum.","e":"Tronco braquiocefálico."},"answer":"b","rationale":"O recorrente esquerdo desce até o mediastino para contornar o arco aórtico (próximo ao ligamento arterioso). O direito contorna a subclávia.","option_rationales":{"a":"Errada. Descrição do lado direito.","b":"Correta. Anatomia aplicada e cirúrgica do pescoço.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia/Topografia"]}', 'ea1d1c95ff331de2202485b88569eaa4', 460, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Lesões nos nervos laríngeos recorrentes durante tireoidectomias podem causar qual sintoma principal?","options":{"a":"Perda do paladar.","b":"Disfagia intensa.","c":"Rouquidão ou perda da voz (disfonia).","d":"Dificuldade em girar o pescoço.","e":"Perda da sensibilidade da face."},"answer":"c","rationale":"Este nervo inerva todos os músculos intrínsecos da laringe, exceto o cricotireoideo.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Anatomia clínica/Cirúrgica.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia/Clínica"]}', '05e74c946e0aac226b3bd5e2fb8a5c09', 461, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''triângulo carótico'' do pescoço é um local importante para palpação do pulso. Qual destes músculos NÃO delimita esse triângulo?","options":{"a":"Esternocleidomastoideo.","b":"Ventre superior do omo-hioide.","c":"Ventre posterior do digástrico.","d":"Trapézio.","e":"Nenhuma das anteriores."},"answer":"d","rationale":"O trapézio delimita o triângulo posterior (occipital e supraclavicular), não o carótico (parte do triângulo anterior).","option_rationales":{"a":"Errada. Limite posterior do triângulo carótico.","b":"Errada. Limite anteroinferior.","c":"Errada. Limite anterosuperior.","d":"Correta. Topografia cervical.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Topografia"]}', '74fed9107e0c1a30749199b3f5a8f68c', 462, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''cavidade nasal'' comunica-se com os seios paranasais. Onde desemboca o ''ducto nasolacrimal'', responsável por drenar as lágrimas?","options":{"a":"Meato nasal superior.","b":"Meato nasal médio.","c":"Meato nasal inferior.","d":"Recesso esfenoetmoidal.","e":"Seio maxilar diretamente."},"answer":"c","rationale":"O meato inferior é o único onde desemboca o ducto nasolacrimal. Os seios drenam principalmente no meato médio e superior.","option_rationales":{"a":"Errada.","b":"Errada. Local de drenagem da maioria dos seios.","c":"Correta. Anatomia das vias aéreas superiores.","d":"Errada. Local de drenagem do seio esfenoide.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', '225a0655cb09330fdc170606aedf4bf1', 463, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''músculo esternocleidomastoideo'' (ECM) é o principal marco do pescoço lateral. Qual nervo craniano o inerva?","options":{"a":"Nervo Vago (X).","b":"Nervo Acessório (XI).","c":"Nervo Hipoglosso (XII).","d":"Nervo Frênico.","e":"Nervos espinais de C1-C2 apenas."},"answer":"b","rationale":"O nervo acessório supre o ECM e o trapézio.","option_rationales":{"a":"Errada.","b":"Correta. Neuroanatomia motora cervical.","c":"Errada.","d":"Errada.","e":"Errada. Recebem ramos cervicais, mas o motor principal é o XI."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', '2a1915c3c3d8c5fd135c4c5bec29807c', 464, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Quantas ''vértebras cervicais'' existem no ser humano e qual delas apresenta o ''processo odontoide'' (dente)?","options":{"a":"5; Atlas (C1).","b":"7; Áxis (C2).","c":"7; Vértebra proeminente (C7).","d":"12; Áxis (C2).","e":"7; Atlas (C1)."},"answer":"b","rationale":"O ser humano tem 7 vértebras cervicais. O áxis (C2) possui o dente que articula com o atlas para rotação da cabeça.","option_rationales":{"a":"Errada.","b":"Correta. Osteologia da coluna cervical.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Osteologia"]}', '486ea0f578ae71c3aa388297c02a620a', 465, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''artéria carótida comum'' se divide em interna e externa. Qual destas estruturas é um ramo da carótida INTERNA no pescoço?","options":{"a":"Artéria Tireoidea Superior.","b":"Artéria Facial.","c":"Artéria Lingual.","d":"Nenhum; a carótida interna não emite ramos no pescoço.","e":"Artéria Maxilar."},"answer":"d","rationale":"A carótida interna sobe pelo espaço carótico sem emitir ramos até entrar no crânio.","option_rationales":{"a":"Errada. Ramo da externa.","b":"Errada. Ramo da externa.","c":"Errada. Ramo da externa.","d":"Correta. Vascularização cervical.","e":"Errada. Ramo terminal da externa."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Angiologia"]}', '3c663ec12ac601550fea209af732debd', 466, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''seio cavernoso'' é um espaço venoso dural crítico na base do crânio. Qual estrutura nervosa atravessa o seio cavernoso INDEPENDENTE da parede lateral (correndo junto à carótida interna)?","options":{"a":"Nervo Oculomotor (III).","b":"Nervo Troclear (IV).","c":"Nervo Abducente (VI).","d":"Nervo Oftálmico (V1).","e":"Nervo Maxilar (V2)."},"answer":"c","rationale":"O nervo abducente e a carótida interna estão ''soltos'' dentro do seio; os outros (III, IV, V1, V2) estão encravados na parede lateral.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Anatomia venosa intracraniana complexa.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia/Angiologia"]}', '6d258f8428b66bc1ce4e57d2f0a08500', 467, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''língua'' tem sensibilidade complexa. Qual nervo é responsável pelo PALADAR (gustação) nos 2/3 anteriores da língua?","options":{"a":"Nervo Trigêmeo (nervo lingual).","b":"Nervo Facial (via corda do tímpano).","c":"Nervo Glossofaríngeo.","d":"Nervo Hipoglosso.","e":"Nervo Vago."},"answer":"b","rationale":"A sensibilidade geral é do lingual (V), mas o paladar é do Facial (VII). No 1/3 posterior, ambos são do glossofaríngeo.","option_rationales":{"a":"Errada. Apenas sensibilidade geral (dor/calor).","b":"Correta. Neurofisiologia/Anatomia dos sentidos.","c":"Errada. Responsável pelo terço posterior.","d":"Errada. Motor.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', '7bb32a6c96cdcf202c6c8d03260ae783', 468, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual o único músculo da mastigação que auxilia na ABERTURA (depressão) da mandíbula via protrusão?","options":{"a":"Masseter.","b":"Temporal.","c":"Pterigoideo medial.","d":"Pterigoideo lateral.","e":"Milohioideo."},"answer":"d","rationale":"O pterigoideo lateral puxa o disco e o côndilo para frente, iniciando a abertura.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Errada.","d":"Correta. Miologia da ATM.","e":"Errada. Auxilia, mas o ''mastigador'' clássico é o pterigoideo."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Miologia"]}', '7a982b592897fb3e88c032791a3b039e', 469, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''ATM'' (Articulação Temporomandibular) possui um elemento que a divide em duas cavidades (superior e inferior). Que estrutura é essa?","options":{"a":"Menisco medial.","b":"Disco articular.","c":"Processo coronoide.","d":"Ligamento esfenomandibular.","e":"Bainha carotídea."},"answer":"b","rationale":"O disco articular de fibrocartilagem torna a ATM uma articulação complexa.","option_rationales":{"a":"Errada. Termo usado no joelho.","b":"Correta. Artrologia da cabeça.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Artrologia"]}', '5190837695bb899bde7565cbaf95f716', 470, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual dos seguintes nervos cranianos NÃO possui função parassimpática (autônoma)?","options":{"a":"Oculomotor (III).","b":"Trigêmeo (V).","c":"Facial (VII).","d":"Glossofaríngeo (IX).","e":"Vago (X)."},"answer":"b","rationale":"Os nervos com fibras parassimpáticas são III, VII, IX e X. O trigêmeo apenas ''empresta'' seus ramos para que essas fibras cheguem ao destino.","option_rationales":{"a":"Errada. Músculos ciliar e esfíncter da pupila.","b":"Correta. Organização do sistema nervoso autônomo craniano.","c":"Errada. Glândulas lacrimal e salivares menores.","d":"Errada. Glândula parótida.","e":"Errada. Vísceras torácicas e abdominais."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', 'f7863b2b4152e32e1d38e2d8bb5180f4', 471, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''artéria meníngea média'' é responsável por hematomas epidurais em fraturas temporais. Ela é ramo de qual artéria principal?","options":{"a":"Artéria Carótida Interna.","b":"Artéria Maxilar (ramo da carótida externa).","c":"Artéria Oftálmica.","d":"Artéria Cerebral Média.","e":"Artéria Temporal Superficial."},"answer":"b","rationale":"A meníngea média entra no crânio pelo forame espinhoso, originando-se da 1ª parte da artéria maxilar.","option_rationales":{"a":"Errada.","b":"Correta. Vascularização aplicada ao trauma craniano.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Angiologia/Clínica"]}', '90479827304d8b75d32387479b2b08fc', 472, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''espaço retrofaríngeo'' é uma região de tecido conjuntivo frouxo entre a faringe e a coluna. Qual a sua importância clínica?","options":{"a":"Local de inserção da língua.","b":"Via de disseminação de infecções da cabeça para o mediastino (via perigosa).","c":"Protege a carótida.","d":"Contém as pregas vocais.","e":"Nenhuma das anteriores."},"answer":"b","rationale":"O espaço retrofaríngeo comunica o pescoço com o mediastino posterior.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia aplicada/Fáscias cervicais.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Topografia/Clínica"]}', '8c45f66ba3506058c40925409b64be43', 473, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual cartilagem da laringe é a única que forma um ANEL COMPLETO ao redor da via aérea?","options":{"a":"Tireoide (pomo de Adão).","b":"Cricoide.","c":"Aritenoide.","d":"Epiglote.","e":"Cuneiforme."},"answer":"b","rationale":"A cartilagem cricoide situa-se na base da laringe e é um anel selado.","option_rationales":{"a":"Errada. Aberta posteriormente (forma de escudo).","b":"Correta. Esplanccnologia respiratória.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', 'e08e2883f62172c0a4dc0c5faa19e0f9', 474, 'draft');